    select 1 from "zaehlung" where "zaehlung".id = p_id and (("zaehlung"."kultur_id" is null or exists (select 1 from "kultur" r714 where r714."id" = "zaehlung"."kultur_id" and exists (select 1 from "garten" r715 where r715."id" = r714."garten_id" and exists (select 1 from "gv" r716 where r716."garten_id" = r715."id" and r716."person_id" = app.current_user_id()::uuid)))))
  )
$$;
create or replace function app.ins_zaehlung_gaertner(p_kultur_id uuid) returns boolean
  language sql stable security definer set search_path = public as $$
  select (p_kultur_id is null or exists (select 1 from "kultur" r717 where r717."id" = p_kultur_id and exists (select 1 from "garten" r718 where r718."id" = r717."garten_id" and exists (select 1 from "gv" r719 where r719."garten_id" = r718."id" and r719."person_id" = app.current_user_id()::uuid))))
$$;
create or replace function app.upd_zaehlung_gaertner(p_id uuid) returns boolean
  language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from "zaehlung" where "zaehlung".id = p_id and (("zaehlung"."kultur_id" is null or exists (select 1 from "kultur" r720 where r720."id" = "zaehlung"."kultur_id" and exists (select 1 from "garten" r721 where r721."id" = r720."garten_id" and exists (select 1 from "gv" r722 where r722."garten_id" = r721."id" and r722."person_id" = app.current_user_id()::uuid)))))
  )
$$;
create or replace function app.del_zaehlung_gaertner(p_id uuid) returns boolean
  language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from "zaehlung" where "zaehlung".id = p_id and (("zaehlung"."kultur_id" is null or exists (select 1 from "kultur" r723 where r723."id" = "zaehlung"."kultur_id" and exists (select 1 from "garten" r724 where r724."id" = r723."garten_id" and exists (select 1 from "gv" r725 where r725."garten_id" = r724."id" and r725."person_id" = app.current_user_id()::uuid)))))
  )
$$;

