--- rev triggers must run as owner ---------------------------------
-- Hasura connected as postgres, so these triggers always had full
-- privileges. Under PostgREST the app roles invoke them; the
-- materialized tables are not directly writable by app roles, so
-- the trigger functions must be security definer.

alter function public.art_rev_set_winning_revision() security definer set search_path = public;
